        margin-top: 16px;
        margin-right: 20px;
        font-size: 9px;
    }

    .jtq-sign-line {
        border-top: 1px solid #000;
        height: 12px;
    }

    .jtq-heading {
        text-align: center;
        font-weight: bold;
        font-size: 11px;
